/**
 * One accordion strip on OB-05. **Deliberately not the ribbon** — the
expanded view and the step panel are their own reads, so a client with
six journeys does not pay for six ribbons on first paint.

 */
export interface ObJourneyStrip {
  id: number;
  product: ObProductRef;
  gateStatus: ObGateStatus;
  /** Null while `gateStatus` is `LOCKED` — nothing is running to colour. */
  rag?: ObJourneyStripRag;
  /**
   * @minimum 0
   * @maximum 100
   */
  percentComplete: number;
  /** Set when this journey is instantiated but held on a **service-level
dependency** — another journey of the same client that has to
complete first (plan §5.5). Distinct from `gateStatus`, which is
about the client's prerequisites: a journey can be past the gate
and still held behind a sibling. Null when nothing holds it.
 */
  heldByJourneyId?: ObJourneyStripHeldByJourneyId;
  /** Σ of this journey's service TATs from its **pinned** template version. */
  totalTatDays?: number;
  /** Working hours consumed: completed services at their recorded
consumption, the active one at its running clock, waiting-on-client
time excluded. **Derived from `ob_step_clock_events` at read time**
for this one client — never a stored aggregate, which could
disagree with the parts it claims to sum.
 */
  utilizedHours?: number;
  /** Every service, in template order — the RAG dots on the collapsed
strip. Not paginated and not pageable: this is one journey's
services, bounded by what the ribbon can render, and the strip
needs all of them to draw any of them.
 */
  steps: ObStepDot[];
}
